use crate::api::client::ApiClient;
use crate::models::{ResultWithDefaultError, TimeEntry};
use crate::utilities;
use chrono::{Datelike, Duration, NaiveDate};
use std::collections::BTreeMap;

const BILLING_UNIT_SECONDS: i64 = 15 * 60;

pub struct BillWeeklyCommand;

fn billed_seconds(entry: &TimeEntry) -> Option<i64> {
    if !entry.billable || entry.stop.is_none() || entry.duration < 0 {
        return None;
    }

    Some(
        ((entry.duration + BILLING_UNIT_SECONDS - 1) / BILLING_UNIT_SECONDS) * BILLING_UNIT_SECONDS,
    )
}

fn week_buckets(entries: &[TimeEntry]) -> BTreeMap<NaiveDate, i64> {
    entries
        .iter()
        .filter_map(|entry| {
            billed_seconds(entry).map(|seconds| {
                let start_date = entry.start.date_naive();
                let monday = start_date
                    - Duration::days(i64::from(start_date.weekday().num_days_from_monday()));
                (monday, seconds)
            })
        })
        .fold(BTreeMap::new(), |mut buckets, (week, seconds)| {
            *buckets.entry(week).or_default() += seconds;
            buckets
        })
}

fn format_output(buckets: &BTreeMap<NaiveDate, i64>) -> String {
    if buckets.is_empty() {
        return "(no data)\n".to_string();
    }

    let total: i64 = buckets.values().sum();
    let mut output = buckets
        .iter()
        .map(|(week, seconds)| format!("{}  {seconds}s", week.format("%Y-%m-%d")))
        .collect::<Vec<_>>();
    output.push(format!("Total  {total}s"));
    output.join("\n") + "\n"
}

impl BillWeeklyCommand {
    pub async fn execute(
        api_client: impl ApiClient,
        since: Option<String>,
        until: Option<String>,
    ) -> ResultWithDefaultError<()> {
        let (since, until) = utilities::normalize_time_entry_list_filters(since, until)?;
        let entries = api_client.get_time_entries_filtered(since, until).await?;
        print!("{}", format_output(&week_buckets(&entries)));
        Ok(())
    }
}

